from typing import List
from .normalize_whitespace import normalize_whitespace

ABBREVIATIONS = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St."}
TERMINATORS = {'.', '!', '?'}
CLOSING = {'"', "'", ')', ']', '}', '>'}
OPENING = {'"', "'", '(', '[', '{', '<'}


def split_sentences(text: str) -> List[str]:
    """
    Split prose into sentences.
    """
    if not text or not text.strip():
        return []

    cleaned = normalize_whitespace(text)
    words = cleaned.split()

    if not words:
        return []

    sentences = []
    current_sentence_words = []

    for i, word in enumerate(words):
        current_sentence_words.append(word)

        if _is_sentence_end(word, words, i):
            sentences.append(" ".join(current_sentence_words))
            current_sentence_words = []

    if current_sentence_words:
        sentences.append(" ".join(current_sentence_words))

    return sentences


def _is_sentence_end(word: str, words: List[str], index: int) -> bool:
    if word in ABBREVIATIONS:
        return False

    if not _has_terminator_suffix(word):
        return False

    if index + 1 >= len(words):
        return False

    next_word = words[index + 1]
    return _starts_new_sentence(next_word)


def _has_terminator_suffix(word: str) -> bool:
    if not word:
        return False
    idx = len(word) - 1
    while idx >= 0 and word[idx] in CLOSING:
        idx -= 1
    if idx < 0:
        return False
    if word[idx] not in TERMINATORS:
        return False
    return True


def _starts_new_sentence(word: str) -> bool:
    if not word:
        return False
    first = word[0]
    if first.isdigit():
        return True
    if first.isupper():
        return True
    if first in OPENING:
        return True
    return False"}}, "messages": []}

